const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const lastTest = new Date(d.last_test_date || d.lastTestDate || Date.now());
  const now = new Date();
  const msPerDay = 1000 * 60 * 60 * 24;
  const daysSince = Math.floor((now - lastTest) / msPerDay);
  const hazard = (d.hazard_level || 'low').toLowerCase();
  const testCycleDays = hazard === 'high' ? 365 : hazard === 'medium' ? 365 : 365;
  const daysOverdue = daysSince - testCycleDays;
  let riskScore = 0;
  if (daysOverdue > 0) riskScore += Math.min(60, daysOverdue / 3);
  if (hazard === 'high') riskScore += 30;
  else if (hazard === 'medium') riskScore += 15;
  if (d.device_type === 'RPZ' && daysOverdue > 0) riskScore += 10;
  out.push({ json: { ...d, days_since_last_test: daysSince, days_overdue: daysOverdue,
    next_due_date: new Date(lastTest.getTime() + testCycleDays * msPerDay).toISOString().slice(0,10),
    risk_score: Math.round(riskScore) } });
}
return out;
